 FROM {_config_catalog}.{_config_schema}.dr_clone_config
 WHERE COALESCE(is_active, 'Y') = 'Y'
 """).collect() # noqa: F821
 except Exception as e: # noqa: BLE001 -- annotation only; never fatal
