 for r in rows:
 key = (str(r["table_catalog"]).strip().lower(),
 str(r["table_schema"]).strip().lower(),
 str(r["table_name"]).strip().lower())
 fqn = f"{r['table_catalog']}.{r['table_schema']}.{r['table_name']}"
 for col in ("east_location", "se_location"):
 path = str(r[col] or "").strip().rstrip("/")
 if path:
 by_path.setdefault((col, path), []).append((key, fqn))

 out = {}
 for (col, path), entries in by_path.items():
 if len(entries) < 2:
 continue
 for key, _fqn in entries:
 others = sorted(f for k, f in entries if k != key)
 if others:
