class MuteJobRunner:
 """Execute a mute / unmute action over parsed targets via the mute manager."""

 def __init__(self, manager, *, dry_run: bool = False) -> None:
 self.manager = manager
 self.dry_run = bool(dry_run)

 def run(self, action: str, scope: str, parsed: ParseResult) -> MuteJobResult:
 action = normalize_action(action)
 scope = normalize_scope(scope)
 muting = action == "MUTE"

 result = MuteJobResult(
 action=action, scope=scope, dry_run=self.dry_run,
 targets_requested=len(parsed.targets), rows_affected=0,
 changed_targets=0, no_match_targets=0,
 warnings=list(parsed.warnings),
 )

 for key in parsed.targets:
 label = ".".join(key)
 try:
 affected = self._apply(muting, scope, key)
 except Exception as exc: # noqa: BLE001 -- one bad target must not abort the rest
 logger.warning("mute_job: %s failed for %s: %s", action, label, str(exc)[:200])
 result.per_target.append(
 {"target": label, "rows_affected": 0, "status": "ERROR",
 "error": str(exc)[:300]}
 )
 continue

 result.rows_affected += affected
 if affected > 0:
 result.changed_targets += 1
 status = ("WOULD_" if self.dry_run else "") + ("MUTED" if muting else "UNMUTED")
 else:
 result.no_match_targets += 1
 # 0 rows = already in the desired state OR no matching config row.
 status = "NO_CHANGE_OR_NO_MATCH"
 result.per_target.append(
 {"target": label, "rows_affected": affected, "status": status}
 )

 logger.info(
 "mute_job: action=%s scope=%s dry_run=%s targets=%d rows_affected=%d "
 "changed=%d no_match=%d warnings=%d",
 action, scope, self.dry_run, result.targets_requested,
 result.rows_affected, result.changed_targets,
 result.no_match_targets, len(result.warnings),
 )
 return result

 def _apply(self, muting: bool, scope: str, key: Tuple[str, ...]) -> int:
 m = self.manager
 if scope == "CATALOG":
 (catalog,) = key
 fn = m.mute_catalog if muting else m.unmute_catalog
 return fn(catalog, dry_run=self.dry_run)
 if scope == "SCHEMA":
 catalog, schema = key
 fn = m.mute_schema if muting else m.unmute_schema
 return fn(catalog, schema, dry_run=self.dry_run)
 catalog, schema, table = key
 fn = m.mute_table if muting else m.unmute_table
 return fn(catalog, schema, table, dry_run=self.dry_run)

"""DeepCloneMuteManager — mute (deactivate) or unmute (activate) tables in config."""

import logging
from typing import List, Optional

from pyspark.sql import DataFrame

from deepclone.config import DeepCloneConfig
from deepclone.helpers import escape_sql

logger = logging.getLogger(__name__)


class DeepCloneMuteManager:
 """Mute (deactivate) or unmute (activate) tables in the dr_clone_config table."""

 def __init__(self, config: DeepCloneConfig, spark) -> None:
 self.config = config
 self.spark = spark

 # -- Public single-table operations ------------------------------------

 def mute_table(self, catalog: str, schema: str, table: str, *, dry_run: bool = False) -> int:
 """Deactivate a single table."""
 return self._toggle("N", catalog, schema, table, dry_run=dry_run)

 def unmute_table(self, catalog: str, schema: str, table: str, *, dry_run: bool = False) -> int:
 """Activate a single table."""
 return self._toggle("Y", catalog, schema, table, dry_run=dry_run)

 # -- Public bulk operations --------------------------------------------

 def mute_tables(self, catalog: str, schema: str, tables: List[str], *, dry_run: bool = False) -> int:
 """Deactivate multiple tables."""
 return sum(self.mute_table(catalog, schema, t.strip(), dry_run=dry_run) for t in tables)

 def unmute_tables(self, catalog: str, schema: str, tables: List[str], *, dry_run: bool = False) -> int:
 """Activate multiple tables."""
 return sum(self.unmute_table(catalog, schema, t.strip(), dry_run=dry_run) for t in tables)

 def mute_schema(self, catalog: str, schema: str, *, dry_run: bool = False) -> int:
 """Deactivate all tables in a schema."""
 return self._toggle("N", catalog, schema, dry_run=dry_run)

 def unmute_schema(self, catalog: str, schema: str, *, dry_run: bool = False) -> int:
 """Activate all tables in a schema."""
 return self._toggle("Y", catalog, schema, dry_run=dry_run)

 def mute_catalog(self, catalog: str, *, dry_run: bool = False) -> int:
 """Deactivate all tables in a catalog."""
 return self._toggle("N", catalog, dry_run=dry_run)

 def unmute_catalog(self, catalog: str, *, dry_run: bool = False) -> int:
 """Activate all tables in a catalog."""
 return self._toggle("Y", catalog, dry_run=dry_run)

 # -- Query helpers -----------------------------------------------------

 def show_muted(
 self, catalog: Optional[str] = None, schema: Optional[str] = None
 ) -> DataFrame:
 """Return DataFrame of muted (inactive) tables."""
 return self._query("N", catalog, schema)

 def show_active(
 self, catalog: Optional[str] = None, schema: Optional[str] = None
 ) -> DataFrame:
 """Return DataFrame of active tables."""
 return self._query("Y", catalog, schema)

 # -- Internal ----------------------------------------------------------

 def _query(
 self, active_val: str, catalog: Optional[str], schema: Optional[str]
 ) -> "DataFrame":
 where = f"COALESCE(is_active, 'Y') = '{active_val}'"
 if catalog:
 where += f" AND table_catalog = '{escape_sql(catalog)}'"
 if schema:
 where += f" AND table_schema = '{escape_sql(schema)}'"
 return self.spark.sql(f"""
 SELECT table_catalog, table_schema, table_name, is_active, updated_ts
 FROM {self.config.config_table}
 WHERE {where}
 ORDER BY table_catalog, table_schema, table_name
 """)

 def _toggle(
 self,
