 where = f"lower(table_catalog) = lower('{escape_sql(catalog)}')"
 if schema:
 where += f" AND lower(table_schema) = lower('{escape_sql(schema)}')"
 if table:
 where += f" AND lower(table_name) = lower('{escape_sql(table)}')"

 cnt = self.spark.sql(f"""
 SELECT COUNT(*) AS cnt FROM

