"""Delta log repair strategy \u2014 FSCK with deep clone fallback."""

import logging
from datetime import datetime
from typing import Dict, Optional

from failover.strategies._helpers import (
 build_success_result,
 count_rows,
 execute_deep_clone,
 read_delta,
)

logger = logging.getLogger(__name__)


def execute(
 spark,
 fully_qualified_name: str,
 table_type: str,
 dr_path: str,
 primary_path: str,
 start_ts: datetime,
 *,
 source_version: Optional[int] = None,
 **_kwargs,
) -> Dict:
 """Repair a broken Delta log via FSCK, with deep clone fallback."""
 try:
 spark.sql(f"FSCK REPAIR TABLE delta.`{primary_path}`")
 local_count = spark.read.format("delta").load(primary_path).count()
 dr_count = read_delta(
 spark, dr_path, table_type, fully_qualified_name, source_version
 ).count()

 if dr_count > 0 and abs(local_count - dr_count) / dr_count <= 0.01:
 return build_success_result(
 "DELTA_LOG_FSCK", dr_count, local_count, 0, 0, start_ts,
 )
 if dr_count == 0:
 return build_success_result(
 "DELTA_LOG_FSCK", 0, local_count, 0, 0, start_ts,
 )
 logger.warning(
 " Row mismatch: local=%d, source=%d. Deep clone fallback.",
 local_count, dr_count,
 )
 except Exception as ex:
 logger.warning(
 " FSCK failed: %s. Deep clone fallback.", str(ex)[:],
 )

 execute_deep_clone(spark, dr_path, primary_path, table_type,
 fully_qualified_name, source_version)
 restored_count = count_rows(spark, primary_path, table_type)

 return build_success_result(
 "DELTA_LOG_CLONE", restored_count, restored_count, 0, 0, start_ts,
 )

