class NotebookLogger:
 """
 Structured logger writing to both the Databricks cell output and an
 in-memory list of entries that is serialised to ADLS at the end of the run.
 Compatible with both serverless and dedicated compute.
 """

 def __init__(self, name: str, level: str = "INFO"):
 self._logger = logging.getLogger(name)
 self._logger.setLevel(getattr(logging, level.upper(), logging.INFO))
 if not self._logger.handlers:
 handler = logging.StreamHandler()
 handler.setFormatter(logging.Formatter(
 "[%(asctime)s] %(levelname)-8s %(name)s — %(message)s",
 datefmt="%Y-%m-%d %H:%M:%S"
 ))
 self._logger.addHandler(handler)
 self.entries: list[dict] = []

 def _record(self, level: str, message: str, table: str = None, error: str = None):
 entry = {
 "timestamp": datetime.now(timezone.utc).isoformat(),
 "level": level,
 "message": message,
 }
 if table: entry["table"] = table
 if error: entry["error"] = error
 self.entries.append(entry)
 log_fn = level.lower() if level != "SUCCESS" else "info"
 getattr(self._logger, log_fn)(message)

 def info(self, msg: str, table: str = None): self._record("INFO", msg, table)
 def warning(self, msg: str, table: str = None): self._record("WARNING", msg, table)
 def success(self, msg: str, table: str = None): self._record("SUCCESS", msg, table)
 def error(self, msg: str, table: str = None, error: str = None):
 self._record("ERROR", msg, table, error)

 def summary(self) -> dict:
 counts = {}
 for e in self.entries:
 counts[e["level"]] = counts.get(e["level"], 0) + 1
 return counts

 @staticmethod
 def _mask_path(path: str) -> str:
 """Masks the storage account name in ADLS paths for cell output display."""
 return re.sub(
 r"(abfss://[^@]+@)[^.]+(\.[^/]+)",
 r"\1***\2",
 path
 )



