def protocol_check(
 spark: SparkSession, target_ref: RefLike, source_ref: RefLike,
 *, tgt_detail: Optional[Dict] = None, src_detail: Optional[Dict] = None,
) -> Tuple[bool, Dict]:
 """Check #6 -- minReaderVersion / minWriterVersion match source.

 Reuses the ``DESCRIBE DETAIL`` dicts already read for the file-match check
 (``tgt_detail`` / ``src_detail``); ``None`` -> fetch here.
 """
 try:
 tgt = tgt_detail if tgt_detail is not None else _describe_detail(spark, target_ref)
 src = src_detail if src_detail is not None else _describe_detail(spark, source_ref)
 t = (tgt.get("minReaderVersion"), tgt.get("minWriterVersion"))
 s = (src.get("minReaderVersion"), src.get("minWriterVersion"))
 matched = t == s
 return matched, {
 "source_min_reader": s[0], "source_min_writer": s[1],
 "target_min_reader": t[0], "target_min_writer": t[1],
 "is_matched": matched,
