@dataclass(frozen=True)
class ValidationResult:
 """Outcome of parameter validation."""
 valid: bool
 errors: List[str] = field(default_factory=list)

 def raise_if_invalid(self) -> None:
 """Raise ``ValueError`` with all errors if validation failed."""
 if not self.valid:
 msg = "Job parameter validation failed:\n - " + "\n - ".join(
 self.errors
 )
 logger.error(msg)
 raise ValueError(msg)


def _require_non_empty(params: Dict, keys: List[str]) -> List[str]:
 """Return error messages for keys that are missing or empty."""
 errors = []
 for k in keys:
 val = params.get(k)
 if val is None or (isinstance(val, str) and not val.strip()):
 errors.append(f"Required parameter '{k}' is missing or empty")
 return errors


def _require_in(params: Dict, key: str, allowed: set,
 label: str = "") -> List[str]:
 """Return an error if *key* is not in *allowed* (case-insensitive)."""
 val = params.get(key, "")
 if isinstance(val, str):
 val = val.strip().upper()
 if val and val not in allowed:
 return [
 f"'{key}' must be one of {sorted(allowed)}, got '{val}'"
 ]
 return []


