 @staticmethod
 def parse_abfss_path(path: str) -> Optional[Tuple[str, str]]:
 """Extract (container, storage_account) from an ABFSS path."""
 if not path:
 return None
 match = _ABFSS_PATTERN.search(path)
 if not match:
 return None
 return match.group(1), match.group(2)

 @staticmethod
 def build_container_url(container: str, storage_account: str) -> str:
 """Build the container-level ABFSS URL."""
 return f"abfss://{container}@{storage_account}.dfs.core.windows.net/"

 def _collect_unique_container_urls(self, paths: List[str]) -> Set[str]:
 """Parse paths and collect unique container-level URLs."""
 urls: Set[str] = set()
 for path in paths:
 parsed = self.parse_abfss_path(path)
 if parsed:
 container, storage_account = parsed
 urls.add(self.build_container_url(container, storage_account))
 return urls

 def _collect_url_schemas(
 self, paths: List[str], path_schemas: Dict[str, str]
 ) -> Dict[str, str]:
 """Map each container URL to a schema name (when one is supplied).

 Multiple sub-paths under the same container collapse to one container
 URL; the last non-empty schema seen wins (they should agree in
 practice, since a container maps 1:1 to a source schema).
 """
 url_schema: Dict[str, str] = {}
 for path in paths:
 schema = (path_schemas.get(path) or "").strip()
 if not schema:
 continue
 parsed = self.parse_abfss_path(path)
 if not parsed:
 continue
 container, storage_account = parsed
 url = self.build_container_url(container, storage_account)
 url_schema[url] = schema
 return url_schema

 @staticmethod
 def _layer_from_schema(schema_name: Optional[str]) -> Optional[str]:
 """Identify the storage layer from a SCHEMA NAME.

 Applies `_SCHEMA_LAYER_RULES` (BDP4 naming conventions). Returns the
 layer name (matching a ``storage_mappings_json`` ``layer`` value) or
 ``None`` when the schema name is empty or matches no rule.
 """
 s = (schema_name or "").strip().lower()
 if not s:
 return None
 for prefix, suffix, layer in _SCHEMA_LAYER_RULES:
 if (not prefix or s.startswith(prefix)) and (
 not suffix or s.endswith(suffix)
 ):
 return layer
 return None

