def align_target_delta_props(spark, source_ref: str, target_ref: str, exc: object = None) -> dict:
 """Upgrade ``target_ref`` to match the source's upgrade-only Delta props.

 Reads both tables' TBLPROPERTIES, picks the upgrade-only properties whose
 target value differs (column mapping mode, protocol min versions, deletion
 vectors, row tracking, CDF, and any ``delta.feature.*``), and applies them
 to the target via a single ALTER so a CREATE OR REPLACE ... DEEP CLONE stops
 failing and stays INCREMENTAL. Any table feature named in ``exc`` (e.g. the
 timestampNtz manual-enablement error) is also enabled. Returns the props
 applied. Raises on failure so the caller can fall back to wipe + full clone.
 """
 def _props(ref: str) -> dict:
 return {r["key"]: r["value"] for r in spark.sql(f"SHOW TBLPROPERTIES {ref}").collect()}

 src, tgt = _props(source_ref), _props(target_ref)
 wanted = {
 k: v for k, v in src.items()
 if (k == "delta.columnMapping.mode"
 or k in ("delta.minReaderVersion", "delta.minWriterVersion",
 "delta.enableDeletionVectors", "delta.enableRowTracking",
 "delta.enableChangeDataFeed")
 or k.startswith("delta.feature."))
 and tgt.get(k) != v
 }
 # Any feature named in the manual-enablement error (e.g. timestampNtz) must
 # be turned on explicitly via delta.feature.<name>=supported.
 if exc is not None:
 import re
 m = re.search(r"manual.*enablement.*?:\s*([A-Za-z0-9_, ]+)", str(exc), re.I | re.S)
 if m:
 for feat in (f.strip() for f in m.group(1).split(",")):
 if feat:
 wanted[f"delta.feature.{feat}"] = "supported"
 if wanted:
 set_clause = ", ".join(f"'{k}'='{v}'" for k, v in wanted.items())
 spark.sql(f"ALTER TABLE {target_ref} SET TBLPROPERTIES ({set_clause})")
 return wanted



