 cols = {f.name.lower() for f in self.spark.table(self.fqn).schema.fields}
 except Exception: # noqa: BLE001 -- table may not exist yet; merge path handles it
 return
 if "sync_direction" in cols:
 return
 try:
 self.spark.sql(
 f"ALTER TABLE {self.fqn} ADD COLUMNS (sync_direction STRING)"
 )
