 def _resolve_foreign_keys(self, all_meta: Sequence[_TableMeta]) -> None:
 """Resolve each captured FK's parent table + columns and attach it to
 the owning table's ``_TableMeta.foreign_keys``.
 A FK row (``self._fk_raw``) knows its child columns and the *identity*
 of the referenced parent key (``unique_constraint_catalog/schema/name``)
 plus, per child column, its ``position_in_unique_constraint`` (the
 1-based slot in the parent key's ordered columns). We look the parent
 key up in ``self._pk_uq_global`` and map each child column to the parent
 column at its position.

 A FK whose parent key is NOT in this batch (parent table out of scope)
 is dropped -- it could not be applied anyway, because the parent table
 would not be registered.
 """
 if not self._fk_raw:
 return
 index = {
 (m.catalog, m.schema, m.table_name): m for m in all_meta
 }
 for fk in self._fk_raw:
 parent = self._pk_uq_global.get(fk["ref"])
 if not parent:
 continue
 pcols = parent["columns"]
 ref_columns: List[str] = []
 ok = True
 for pos in fk["pos"]:
 if pos is None or pos < 1 or pos > len(pcols):
 ok = False
 break
 ref_columns.append(pcols[pos - 1])
 if not ok or len(ref_columns) != len(fk["columns"]):
 continue
 m = index.get((fk["catalog"], fk["schema"], fk["table"]))
 if m is None:
 continue
 m.foreign_keys.append({
 "name": fk["name"],
 "columns": fk["columns"],
 "ref_table": (
 f"`{parent['catalog']}`.`{parent['schema']}`.`{parent['table']}`"
 ),
 "ref_columns": ref_columns,
 })

 @staticmethod
 def _key_constraints_json(m: _TableMeta) -> Optional[str]:
 """Serialise a table's PK + FK metadata to JSON.

 Returns:
 * the JSON object when a PK and/or FK was captured;
 * ``'{}'`` when the constraint query SUCCEEDED but the table has no
 constraints -- a "checked, none found" marker so the row is not
 re-extracted on every run;
 * ``None`` when the constraint query NEVER ran or FAILED -- leaves
 ``key_constraints`` NULL so a later run retries the extraction
 (prevents a failed/legacy extraction from permanently losing a PK).
 """
 obj: Dict[str, object] = {}
 if m.primary_key:
 obj["primary_key"] = m.primary_key
 if m.foreign_keys:
 obj["foreign_keys"] = m.foreign_keys
 if obj:
 return json.dumps(obj)
 return "{}" if m.constraints_extracted else None

