 def _fill_create_ddls(self, views: List[ViewDefinition]) -> None:
 """Populate ``create_ddl`` for each view via SHOW CREATE TABLE, in
 parallel (independent per-view round-trips)."""
 if not views:
 return
 workers = min(self.max_workers, len(views))
 if workers <= 1:
 for vd in views:
 vd.create_ddl = self._show_create(vd)
 return
 with ThreadPoolExecutor(max_workers=workers) as pool:
 for vd, ddl in zip(views, pool.map(self._show_create, views)):
 vd.create_ddl = ddl

 def _attach_schema_locations(self, views: List[ViewDefinition]) -> None:
 """Resolve each distinct schema's source + East location once and stamp
 it onto every view in that schema (denormalized, like the table register
 stores ``east_schema_location`` on each table row)."""
 cache: dict = {}
 for vd in views:
 key = (vd.catalog, vd.schema)
 if key not in cache:
 cache[key] = self.schema_resolver.resolve(vd.catalog, vd.schema)
 src, tgt = cache[key]
 vd.source_schema_location = src or ""
 vd.target_schema_location = tgt or ""
 located = sum(1 for v in views if v.target_schema_location)
 self.log.info(
 "resolved schema locations: %d schema(s); %d view(s) carry an East "
 "managed location (rest inherit from the catalog)",
 len(cache), located,
 )

 # -- UC metadata capture (tags / column comments / properties) ----------
 # CREATE OR REPLACE VIEW carries only the SQL + the view comment. Tags,
 # column comments/tags and (user) properties live in the source metastore
 # and must be captured here and re-applied on East. Mirrors the table
 # register's dr_clone_table_metadata extraction. Grants are handled
 # elsewhere. Internal view.* / delta.* / spark.* properties are excluded.
 _RESERVED_PROPERTY_PREFIXES = ("view.", "delta.", "spark.")
 _RESERVED_PROPERTY_KEYS = {"transient_lastddltime"}

 def _attach_view_metadata(self, views: List[ViewDefinition]) -> None:
 """Capture view tags, column comments/tags and user properties for every
 extracted view. Bulk per-catalog reads for tags/columns (one set of
 information_schema queries per catalog); per-view SHOW TBLPROPERTIES for
 properties. Best-effort: a failure leaves that slice empty, never raises.
 """
 by_catalog: dict = {}
 for vd in views:
 by_catalog.setdefault(vd.catalog, []).append(vd)

 for cat, vlist in by_catalog.items():
 try:
 self._attach_catalog_view_metadata(cat, vlist)
 except Exception as exc: # noqa: BLE001 - decorative, never fatal
