 "view-metadata capture failed for catalog %s: %s",
 cat, str(exc)[:300],
 )

 # Properties are per-object (no information_schema view exists for them).
 if views:
 workers = min(self.max_workers, len(views))
 if workers <= 1:
 for vd in views:
 vd.view_properties = self._show_view_properties(vd)
 else:
 with ThreadPoolExecutor(max_workers=workers) as pool:
 for vd, props in zip(
 views, pool.map(self._show_view_properties, views)
 ):
 vd.view_properties = props

 with_tags = sum(1 for v in views if v.view_tags)
 with_colmeta = sum(1 for v in views if v.column_metadata)
 with_props = sum(1 for v in views if v.view_properties)
 self.log.info(
 "view metadata captured: %d w/ view-tags, %d w/ column-metadata, "
 "%d w/ properties (of %d views)",
 with_tags, with_colmeta, with_props, len(views),
 )

 def _attach_catalog_view_metadata(
 self, catalog: str, vlist: List[ViewDefinition],
 ) -> None:
