 for r in self.spark.sql(f"""
 SELECT table_schema, table_name, column_name, ordinal_position,
 COALESCE(comment, '') AS comment
 FROM {c}.information_schema.columns
 {where}
 ORDER BY table_schema, table_name, ordinal_position
 """).collect():
