 key: {c2["name"]: i for i, c2 in enumerate(cols)}
 for key, cols in cols_by_key.items()
 }

 # Column tags.
 try:
 where = f"WHERE schema_name IN ({in_list})" if in_list else ""
 for r in self.spark.sql(f"""
 SELECT schema_name, table_name, column_name, tag_name, tag_value
 FROM {c}.information_schema.column_tags
 {where}
 """).collect():
 key = (r["schema_name"], r["table_name"])
