"""Tests for shared/progress_render.py -- the dashboard's pure logic.

These are the calculations most likely to go quietly wrong: a divide-by-zero on
a tier with no tables, an ETA that lies because it was computed against the
job's elapsed time rather than the group's, or a stall flag that fires on every
large table. All of it is invisible until someone is staring at a bad number
mid-run, so it is tested here rather than discovered there.
"""

import time

from shared.progress_render import (
 aggregate,
