)

NOW = 1_700_000_000.0


def _utc(ts):
 return time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime(ts))


def _hb(test_type="full_diff", tier="l", chunk=0, done=0, total=289,
 errors=0, state="running", started_ago=3600, updated_ago=0):
 return {
 "test_type": test_type, "tier": tier, "chunk": chunk,
 "done": done, "total": total, "errors": errors, "state": state,
 "started_utc": _utc(NOW - started_ago),
 "updated_utc": _utc(NOW - updated_ago),
 }


