"""Unit tests for the drift-aware content hashing used by the metadata
apply phase (shared.table_metadata)."""

import pytest

from shared.table_metadata import (
 compute_constraints_hash,
 compute_metadata_hash,
 compute_schema_fingerprint,
)


@pytest.mark.unit
class TestComputeMetadataHash:

 def test_stable_for_identical_input(self):
 meta = {
 "table_comment": "customer table",
 "table_tags": {"pii": "true", "domain": "sales"},
 "columns": [
 {"name": "id", "comment": "pk", "tags": {"key": "1"}},
 {"name": "name", "comment": "", "tags": {}},
 ],
 }
 assert compute_metadata_hash(meta) == compute_metadata_hash(dict(meta))

 def test_tag_order_does_not_change_hash(self):
 a = {"table_comment": "", "table_tags": {"a": "1", "b": "2"}, "columns": []}
 b = {"table_comment": "", "table_tags": {"b": "2", "a": "1"}, "columns": []}
 assert compute_metadata_hash(a) == compute_metadata_hash(b)

 def test_column_order_does_not_change_hash(self):
 a = {
 "table_comment": "", "table_tags": {},
 "columns": [
 {"name": "b", "comment": "x", "tags": {}},
 {"name": "a", "comment": "y", "tags": {}},
 ],
 }
 b = {
 "table_comment": "", "table_tags": {},
 "columns": [
 {"name": "a", "comment": "y", "tags": {}},
 {"name": "b", "comment": "x", "tags": {}},
 ],
 }
 assert compute_metadata_hash(a) == compute_metadata_hash(b)

 def test_changed_comment_changes_hash(self):
 a = {"table_comment": "old", "table_tags": {}, "columns": []}
 b = {"table_comment": "new", "table_tags": {}, "columns": []}
 assert compute_metadata_hash(a) != compute_metadata_hash(b)

 def test_changed_tag_value_changes_hash(self):
 a = {"table_comment": "", "table_tags": {"pii": "true"}, "columns": []}
 b = {"table_comment": "", "table_tags": {"pii": "false"}, "columns": []}
 assert compute_metadata_hash(a) != compute_metadata_hash(b)

 def test_changed_column_comment_changes_hash(self):
 a = {"table_comment": "", "table_tags": {},
 "columns": [{"name": "id", "comment": "a", "tags": {}}]}
 b = {"table_comment": "", "table_tags": {},
 "columns": [{"name": "id", "comment": "b", "tags": {}}]}
 assert compute_metadata_hash(a) != compute_metadata_hash(b)

 def test_missing_and_empty_fields_are_equivalent(self):
 a = {"table_comment": "", "table_tags": {}, "columns": []}
 b = {}
 assert compute_metadata_hash(a) == compute_metadata_hash(b)

 def test_returns_hex_string(self):
 h = compute_metadata_hash({"table_comment": "x"})
 assert isinstance(h, str) and len(h) == 64


