@pytest.mark.unit
class TestComputeSchemaFingerprint:

 def test_stable_for_identical_input(self):
 cols = [
 {"name": "id", "data_type": "int", "nullable": "NO"},
 {"name": "name", "data_type": "string", "nullable": "YES"},
 ]
 assert compute_schema_fingerprint(cols) == compute_schema_fingerprint(list(cols))

 def test_ignores_comment_and_tags(self):
 a = [{"name": "id", "data_type": "int", "nullable": "NO",
 "comment": "pk", "tags": {"k": "1"}}]
 b = [{"name": "id", "data_type": "int", "nullable": "NO",
 "comment": "different", "tags": {}}]
 assert compute_schema_fingerprint(a) == compute_schema_fingerprint(b)

 def test_column_order_changes_hash(self):
 a = [
 {"name": "a", "data_type": "int", "nullable": "NO"},
 {"name": "b", "data_type": "string", "nullable": "YES"},
 ]
 b = [
 {"name": "b", "data_type": "string", "nullable": "YES"},
 {"name": "a", "data_type": "int", "nullable": "NO"},
 ]
 assert compute_schema_fingerprint(a) != compute_schema_fingerprint(b)

 def test_changed_type_changes_hash(self):
 a = [{"name": "amount", "data_type": "decimal(10,2)", "nullable": "YES"}]
 b = [{"name": "amount", "data_type": "decimal(18,2)", "nullable": "YES"}]
 assert compute_schema_fingerprint(a) != compute_schema_fingerprint(b)

 def test_changed_nullability_changes_hash(self):
 a = [{"name": "id", "data_type": "int", "nullable": "NO"}]
 b = [{"name": "id", "data_type": "int", "nullable": "YES"}]
 assert compute_schema_fingerprint(a) != compute_schema_fingerprint(b)

 def test_added_column_changes_hash(self):
 a = [{"name": "id", "data_type": "int", "nullable": "NO"}]
 b = a + [{"name": "ts", "data_type": "timestamp", "nullable": "YES"}]
 assert compute_schema_fingerprint(a) != compute_schema_fingerprint(b)

 def test_empty_and_none_equivalent(self):
 assert compute_schema_fingerprint([]) == compute_schema_fingerprint(None)

 def test_missing_type_and_nullable_treated_as_empty(self):
 a = [{"name": "id"}]
 b = [{"name": "id", "data_type": "", "nullable": ""}]
 assert compute_schema_fingerprint(a) == compute_schema_fingerprint(b)

 def test_returns_hex_string(self):
 h = compute_schema_fingerprint([{"name": "id", "data_type": "int"}])
 assert isinstance(h, str) and len(h) == 64


